fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    input
        .into_iter()
        .map(|(a, b)| {
            if a == b {
                0
            } else if a < b {
                // need to increase by (b - a)
                let d = b - a;
                // one odd‐increment if d is odd, otherwise two odds sum to d
                if d % 2 != 0 { 1 } else { 2 }
            } else {
                // a > b, need to decrease by (a - b)
                let d = a - b;
                // one even‐decrement if d is even, otherwise pair an odd‐increment and even‐decrement
                if d % 2 == 0 { 1 } else { 2 }
            }
        })
        .collect()
}

