    #[test]
    fn basic_cases() {
        // 0 moves when equal
        assert_eq!(solve(vec![(5, 5)]), vec![0]);

        // positive difference
        // odd gap → 1 move (add the odd gap)
        assert_eq!(solve(vec![(3, 8)]), vec![1]);
        // even gap → 2 moves (sum of two odds)
        assert_eq!(solve(vec![(3, 7)]), vec![2]);

        // negative difference
        // even gap → 1 move (subtract the even gap)
        assert_eq!(solve(vec![(10, 4)]), vec![1]);
        // odd gap → 2 moves (e.g. +1 then subtract d+1)
        assert_eq!(solve(vec![(10, 3)]), vec![2]);
    }

